1	import "server-only";
2	import { createClient } from "@/lib/supabase/server";
3	import { createAdminClient } from "@/lib/supabase/admin";
4	import { PUBLIC_PROVIDER_COLUMNS } from "@/lib/supabase/types";
5	import {
6	  type AdminMetricsAlerts,
7	  type AdminMetricsOperational,
8	  type AdminMetricsStrategic,
9	  type AvailabilitySlotRow,
10	  type BookingRow,
11	  type PaymentRow,
12	  type PayoutRow,
13	  type ProfileRow,
14	  type ProviderRow,
15	  type PublicProvider,
16	  type ReportRow,
17	  type ReviewRow,
18	  type SessionRow,
19	} from "@/lib/supabase/types";
20	import { type BrowseFilters } from "@/lib/validation/schemas";
21	
22	/**
23	 * Central data-access layer (CLAUDE.md). All reads go through the RLS-enforced
24	 * server client, so each caller only sees rows they're entitled to. Public
25	 * provider reads select PUBLIC_PROVIDER_COLUMNS — never the server-only
26	 * bg_check_ref / payout_account_ref (no column-level RLS, so we scope here).
27	 */
28	
29	/** Approved providers for discovery, with optional filters. */
30	export async function listApprovedProviders(
31	  filters: BrowseFilters = {},
32	): Promise<PublicProvider[]> {
33	  const supabase = await createClient();
34	  let query = supabase
35	    .from("providers")
36	    .select(PUBLIC_PROVIDER_COLUMNS)
37	    .eq("status", "approved");
38	
39	  if (filters.topic) query = query.contains("topics", [filters.topic]);
40	  if (filters.language) query = query.contains("languages", [filters.language]);
41	  if (filters.availableNow) query = query.eq("is_available_now", true);
42	  if (typeof filters.maxPriceCents === "number") {
43	    query = query.lte("price_block_30_cents", filters.maxPriceCents);
44	  }
45	
46	  const { data, error } = await query.order("rating_avg", { ascending: false });
47	  if (error) throw error;
48	  return (data ?? []) as unknown as PublicProvider[];
49	}
50	
51	/** A single approved provider's public profile, or null. */
52	export async function getApprovedProvider(
53	  id: string,
54	): Promise<PublicProvider | null> {
55	  const supabase = await createClient();
56	  const { data, error } = await supabase
57	    .from("providers")
58	    .select(PUBLIC_PROVIDER_COLUMNS)
59	    .eq("id", id)
60	    .eq("status", "approved")
61	    .maybeSingle();
62	  if (error) throw error;
63	  return (data as unknown as PublicProvider | null) ?? null;
64	}
65	
66	/** Providers in a given status (admin only — RLS lets admins read all). */
67	export async function listProvidersByStatus(
68	  status: ProviderRow["status"],
69	): Promise<ProviderRow[]> {
70	  const supabase = await createClient();
71	  const { data, error } = await supabase
72	    .from("providers")
73	    .select("*")
74	    .eq("status", status)
75	    .order("created_at", { ascending: true });
76	  if (error) throw error;
77	  return data ?? [];
78	}
79	
80	export interface AdminMetrics {
81	  strategic: AdminMetricsStrategic;
82	  operational: AdminMetricsOperational;
83	  alerts: AdminMetricsAlerts;
84	}
85	
86	/**
87	 * Read the precomputed admin metric views. Access to the views is revoked from
88	 * anon/authenticated, so this uses the service-role client — callers MUST guard
89	 * with requireRole("admin") first.
90	 */
91	export async function getAdminMetrics(): Promise<AdminMetrics> {
92	  const admin = createAdminClient();
93	  const [strategic, operational, alerts] = await Promise.all([
94	    admin.from("admin_metrics_strategic").select("*").single(),
95	    admin.from("admin_metrics_operational").select("*").single(),
96	    admin.from("admin_metrics_alerts").select("*").single(),
97	  ]);
98	  if (strategic.error) throw strategic.error;
99	  if (operational.error) throw operational.error;
100	  if (alerts.error) throw alerts.error;
101	  return {
102	    strategic: strategic.data,
103	    operational: operational.data,
104	    alerts: alerts.data,
105	  };
106	}
107	
108	/** Approved providers the customer has favorited (for the customer dashboard). */
109	export async function listFavoriteProviders(
110	  customerId: string,
111	): Promise<PublicProvider[]> {
112	  const supabase = await createClient();
113	  const { data: favs, error } = await supabase
114	    .from("favorites")
115	    .select("provider_id")
116	    .eq("customer_id", customerId);
117	  if (error) throw error;
118	  const ids = (favs ?? []).map((f) => f.provider_id);
119	  if (ids.length === 0) return [];
120	  const { data, error: pErr } = await supabase
121	    .from("providers")
122	    .select(PUBLIC_PROVIDER_COLUMNS)
123	    .in("id", ids)
124	    .eq("status", "approved");
125	  if (pErr) throw pErr;
126	  return (data ?? []) as unknown as PublicProvider[];
127	}
128	
129	/** Provider ids the customer has favorited. */
130	export async function listFavoriteIds(customerId: string): Promise<string[]> {
131	  const supabase = await createClient();
132	  const { data, error } = await supabase
133	    .from("favorites")
134	    .select("provider_id")
135	    .eq("customer_id", customerId);
136	  if (error) throw error;
137	  return (data ?? []).map((f) => f.provider_id);
138	}
139	
140	/** All reports (admin only — RLS lets admins read all), newest first. */
141	export async function listReports(): Promise<ReportRow[]> {
142	  const supabase = await createClient();
143	  const { data, error } = await supabase
144	    .from("reports")
145	    .select("*")
146	    .order("created_at", { ascending: false });
147	  if (error) throw error;
148	  return data ?? [];
149	}
150	
151	/** Profiles by id (admin reads all via RLS) — to name reporters/targets. */
152	export async function getProfilesByIds(
153	  ids: string[],
154	): Promise<Map<string, ProfileRow>> {
155	  const clean = ids.filter(Boolean);
156	  if (clean.length === 0) return new Map();
157	  const supabase = await createClient();
158	  const { data, error } = await supabase
159	    .from("profiles")
160	    .select("*")
